contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // caller triggers owned() via this contract to observe whether owner becomes this contract (msg.sender) or tx.origin
    function run(address deployer, address caller) public {
        // preconditions: deployer is initial owner and different from caller to distinguish msg.sender vs tx.origin
        require(deployer != caller);

        // The test contract is used as an intermediate caller: we simulate that 'caller' will call this function
        // but since we cannot change msg.sender here, we require that this contract is funded/authorized externally.
        // Instead, we drive the contract c through two steps that reflect the difference:
        // 1) Ensure current owner equals deployer (observed via public getter)
        require(c.owner() == deployer);

        // 2) Call c.owned() through this contract (so inside c, msg.sender == address(this) and tx.origin == caller)
        // We must perform the state-changing call as its own top-level statement per rules.
        c.owned();

        // After the call, under the original correct contract P, onlyOwner prevented non-owner from calling owned(),
        // so owner must still equal deployer. Under the mutant M (owner := tx.origin), if the onlyOwner check passed
        // (i.e., this contract was owner), the owner would become tx.origin (caller) and thus differ from deployer.
        // We assert the general rule: owner remains deployer.
        assert(c.owner() == deployer);
    }

    // Allow this contract to receive ETH if needed by environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // precondition: caller is not zero address
        require(caller != address(0));
        // We must observe that only the current owner can change owner via owned().
        // Save current owner
        address before = c.owner();
        // Try to call owned() from the provided caller by using a call() with abi-encoded selector.
        // Build calldata for owned(): function owned() has selector bytes4(keccak256("owned()"))
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("owned()")));
        // perform the external call: we expect it succeeds or reverts depending on onlyOwner;
        // capture success but not revert details
        (bool success, ) = address(caller).call(abi.encodeWithSelector(this._forward.selector, address(c), data));
        // After attempt, owner must be either unchanged or equal to before. For original contract P, call from non-owner cannot change owner, so owner stays equal to before.
        address after = c.owner();
        assert(after == before);
    }
    // helper to forward a low-level call to target; this contract will be used as the callee in the external call above
    function _forward(address target, bytes calldata data) external returns (bytes memory) {
        (bool ok, bytes memory ret) = target.call(data);
        require(ok);
        return ret;
    }
    receive() external payable { }
}

