        address before = c.owner();
        // call owned() as the supplied caller by using low-level call to simulate calling from that address
        // we must have this contract perform the call; create calldata for owned(): function signature
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        // record owner after call
        address after = c.owner();
        // General rule: if the caller (msg.sender of the call) was not the owner before, owner should remain unchanged
        // Since we cannot change msg.sender of this contract's call, require that this contract is not the owner to make rule meaningful
        // but we must express the general property: if before != address(this) then after == before
        assert(before != address(this) || after == address(this));
    }
    receive() external payable {}
}

