contract InvMutTest_Fix is Test {
    C c;

    function setUp() public { c = new C(0, 0, 0); }

    // We must have exactly the function name and signature required by the harness. Replacing previous one.
    function testFuzz_property(uint256 burnAmount) public {
        // redeploy C with a fuzzed deployer EOA so we can create a situation where an intermediate contract calls owned()
        address deployer = address(uint160(uint256(keccak256(abi.encodePacked(burnAmount, block.timestamp)))));
        // ensure deployer is non-zero
        if (deployer == address(0)) deployer = address(1);
        vm.prank(deployer);
        C local = new C(0, "t", "t");

        // Deploy a Forwarder contract whose purpose is to call local.owned() when forwarded by deployer.
        Forwarder f = new Forwarder(address(local));

        // Now have deployer (the owner) call the forwarder so that forwarder calls local.owned().
        // When deployer calls f.forwardOwned(), tx.origin == deployer, msg.sender inside local.owned() == address(f).
        // onlyOwner in local requires msg.sender == owner. Since owner == deployer and msg.sender == f, this call would revert.
        // To make the onlyOwner check pass, we first set owner to the forwarder by having deployer call local.owned() directly (owner becomes deployer in ref and mutant), then make deployer set owner to forwarder by calling local.owned() via a call where msg.sender equals owner. Achieve by having deployer call f.becomeAndCallOwned() which will make f call local.owned() with msg.sender == f and tx.origin == deployer, but onlyOwner will fail unless owner == f. So instead we do this sequence:
        // 1) deployer calls local.owned() directly: owner becomes deployer (both ref and mutant)
        vm.prank(deployer);
        local.owned();
        assert(local.owner() == deployer);

        // 2) Now have deployer transfer ownership to the forwarder in a way that reference and mutant differ: call local.owned() but via a context where onlyOwner sees deployer as msg.sender but local.owned() sees tx.origin for mutant assignment. We implement a helper that, when called by deployer, executes an external call into local that sets owner = tx.origin in the mutant path.
        // Our Forwarder has a function called callOwnedAsForwarder() that uses the fact that when deployer calls f.callOwnedAsForwarder(), inside that function f will call local.owned(); inside local, msg.sender == address(f) and tx.origin == deployer. onlyOwner will compare address(f) (msg.sender) to current owner (deployer) and revert. To bypass onlyOwner, we have forwarder use a trick: it performs a call where it sets msg.sender to deployer via a low-level call? That's not possible.

        // Given limitations of forging onlyOwner bypass in this constrained test, we instead assert a simpler universal property that is broken by the mutant: If owner equals some address X, and X calls owned() again, owner becomes X in the reference (idempotent). In the mutant, if X is a contract and the call is relayed so that tx.origin differs, owner may become tx.origin instead of X. We can demonstrate this by making X be a contract that calls local.owned() while being itself called by an EOA deployer. Sequence:
        // - Deploy an intermediary contract OwnerContract whose constructor sets itself as owner by calling local.owned() via vm.prank(ownerEOA) when creating OwnerContract.
        // To keep this implementable: we will create OwnerContract and have deployer call a function on it that makes it call local.owned(); then OwnerContract will be owner (in reference owner=OwnerContract, in mutant owner=tx.origin which is deployer). Then OwnerContract (owner in reference) calls local.burn(burnAmount). After burn, owner should remain OwnerContract in reference, but in mutant owner will be deployer (since owned() earlier set owner to tx.origin). So we check owner after burn.

        // Create OwnerContract and have deployer make it call local.owned()
        OwnerContract oc = new OwnerContract(address(local));
        vm.prank(deployer);
        oc.becomeOwner();

        // At this point: in reference, owner should be address(oc). In mutant, owner would be deployer because owned() would set tx.origin.
        // We now have oc call local.burn(burnAmount) as the owner. First ensure oc has enough balance to burn: the token balance initially assigned to deployer (constructor) is zero supply; however constructor gave deployer totalSupply of 0. So to avoid underflow, we bound burnAmount to 0.
        burnAmount = bound(burnAmount, 0, 0);

        // Now have oc call burn
        oc.callBurn(burnAmount);

        // Final check: in the reference, owner remains oc. In the mutant, owner becomes deployer. So assert that owner == address(oc).
        // This single assert is satisfied for reference for all inputs and violated by the mutant for some inputs (when oc is a contract and became owner via forwarded call).
        assertTrue(local.owner() == address(oc));
    }
}

// Helper contracts
contract Forwarder {
    C c;
    constructor(address _c) { c = C(_c); }
    function callOwnedAsForwarder() external {
        c.owned();
    }
}

contract OwnerContract {
    C c;
    constructor(address _c) { c = C(_c); }
    function becomeOwner() external {
        // When an EOA calls this, tx.origin == the EOA; when this contract calls c.owned(), inside c msg.sender == address(this) and tx.origin is the EOA.
        c.owned();
    }
    function callBurn(uint256 v) external {
        c.burn(v);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, 0, 0); }

    // fuzz the attacker/deployer address that will act as an intermediate contract owner
    function testFuzz_property(address helperDeployer) public {
        // keep helperDeployer broadly admissible but avoid address(0)
        vm.assume(helperDeployer != address(0));

        // 1) deploy a small intermediate contract from helperDeployer that will call c.owned()
        // We need to ensure helperDeployer is the msg.sender for the deploy and the contract's calls.
        // Fund helperDeployer so it can deploy and call.
        vm.deal(helperDeployer, 1 ether);
        vm.prank(helperDeployer);
        Intermediate inter = new Intermediate(c);

        // 2) have that intermediate call owned() so that owner is set using msg.sender in reference
        // For reference C, owner becomes address(inter); for mutant M owned() would set tx.origin (helperDeployer)
        vm.prank(address(inter));
        inter.callOwned();

        // 3) now call burn from an EOA (the test runner address) — ensure caller has balance
        // give c some tokens to the test address by minting via owner: owner is address(inter)
        // We must impersonate the owner to mint. Owner is address(inter) in reference, so prank it.
        vm.prank(address(inter));
        c.mintToken(address(this), 1);

        // ensure this contract has token to burn
        // Now perform burn as the owner (must be onlyOwner). For reference, onlyOwner requires msg.sender == owner.
        // To satisfy onlyOwner when owner == address(inter), we have the intermediate contract perform burn.
        vm.prank(address(inter));
        // call burn(1) via the intermediate so msg.sender == address(inter)
        inter.callBurn(1);

        // After this sequence, for the reference contract owner remains address(inter).
        // For the mutant that uses tx.origin in owned(), owner would have been set to helperDeployer when owned() was called from inter,
        // and after the intermediate's burn the owner would then differ from address(inter).

        // Single assertion reading c's public getter owner()
        assertTrue(c.owner() == address(inter));
    }
}

contract Intermediate {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function callOwned() public {
        c.owned();
    }
    function callBurn(uint256 v) public {
        c.burn(v);
    }
}
